import itertools

def all_block_permutations(s, block_size):
    assert len(s) % block_size == 0
    blocks = [s[i:i+block_size] for i in range(0, len(s), block_size)]
    perms = set(itertools.permutations(blocks))
    results = ["".join(p) for p in perms]
    return results

def reverse_blocks(s, block_size):
    assert len(s) % block_size == 0
    blocks = [s[i:i+block_size] for i in range(0, len(s), block_size)]
    rev_blocks = [b[::-1] for b in blocks]
    return "".join(rev_blocks)


def main():
    S = 'yevZd$i"'
    out = set()
    # Permutations of block sizes
    for bs in [2,3,4]:
        if len(S) % bs != 0:
            continue
        perms = all_block_permutations(S, bs)
        out.update(perms)
        # Reverse all blocks in each permutation
        for p in perms:
            rev_blocks = reverse_blocks(p, bs)
            out.add(rev_blocks)
    # Full reversal
