import itertools

def bit_reverse(b):
    return int('{:08b}'.format(b)[::-1], 2)

def apply_ops(val, ops):
    for op in ops:
        if op == 'NOT':
            val = 255 - val
        elif op == 'REV':
            val = bit_reverse(val)
        elif op == 'XOR20':
            val = val ^ 0x20
    return val

def generate_op_orders():
    ops = ['NOT', 'REV', 'XOR20']
    res = []
    # 0, 1, 2, or 3 operations can be applied (any order)
    for i in range(4):
        for opchoice in itertools.permutations(ops, i):
            res.append(list(opchoice))
    return res

def process(s):
    op_orders = generate_op_orders()
    out = set()
    pair_indices = list(range(0, len(s), 2))
    for opseqs in itertools.product(
            op_orders, repeat=len(s)//2*2 if len(s)%2==0 else ((len(s)//2)+1)):
        chars = list(s)
        for i, idx in enumerate(pair_indices):
            if idx+1 < len(s):
                c1, c2 = chars[idx], chars[idx+1]
                # Swap order
                swapped = [c2, c1]
                # Apply chosen ops to each swapped char
                for oA in op_orders:
                    for oB in op_orders:
                        valA = apply_ops(ord(swapped[0]), oA)
                        valB = apply_ops(ord(swapped[1]), oB)
                        chars_out = chars[:idx] + [chr(valA%256), chr(valB%256)] + chars[idx+2:]
                        candidate = ''.join(chars_out)
                        if 'flag{' in candidate:
