import base64
import binascii
import uu
import io

s = 'wxqvn$Zae${deyZv$d"i'

results = []

def try_base64(s):
    try:
        b = base64.b64decode(s)
        return ('base64', b)
    except Exception as e:
        return ('base64', None)

def try_hex(s):
    try:
        b = binascii.unhexlify(s)
        return ('hex', b)
    except Exception as e:
        return ('hex', None)

def try_ascii85(s):
    try:
        b = base64.a85decode(s)
        return ('ascii85', b)
    except Exception as e:
        return ('ascii85', None)

def try_uu(s):
    try:
        inp = io.StringIO(s)
        out = io.BytesIO()
        uu.decode(inp, out)
        return ('uu', out.getvalue())
    except Exception as e:
        return ('uu', None)

decoders = [try_base64, try_hex, try_ascii85, try_uu]

for fn in decoders:
    typ, result = fn(s)
    if result:
        try:
            print(f"{typ} ASCII: {result.decode()}")
        except Exception:
            print(f"{typ} HEX:")
            print(result.hex())
    else:
        print(f"{typ}: No valid output")
